  (forall a, S - 80 - 2560 <= a < S - 80 -> M1 (Z_to_bv 64 a) <> None) -> L5.defined M1 dst len ->
  (exists q A, In (q, A) LBo /\ q <= dst /\ dst + len <= q + A) ->
  mem_ok M1.
